# -*- coding: utf-8 -*-

"""
featured_block_generator.py

* Scans every markdown file under the vault’s CONTENT_DIR (default: “content”).
* Looks for a front‑matter key called **featured_data**.
* Extracts the description, image and a list of “fun fact” keys.
* Resolves those keys against the **%%‑section** that follows the markdown body
  (the section where you write the actual text of the description, the image
  wikilink, and the fact strings).
* Writes a JSON report (all extracted pages) to
  content/Meta/Programs/debug/featured_block_generator/extracted_featured.json
* Loads the home page file **_index.md**, replaces the *first* call‑out box it
  finds with a freshly generated block that looks like

  > [!tip] Featured Article & Fun Facts
  > > [!note] Featured Article
  > > {description}
  > > {image}
  > 
  > > [!info] Did you know...
  > > - {random‑fact‑1}
  > > - {random‑fact‑2}
  > > ...

* The **featured article** (its title, description & image) is chosen **randomly**
  from the pages that contain `featured_data`.
* The **fun facts** are chosen **randomly from the union of every page’s
  `fun_facts` list** (not just from the featured article).
* Supports a dry‑run mode (`DRY_RUN=True`) where nothing is written,
  only a summary is printed.
"""

# ----------------------------------------------------------------------
# 1️⃣ CONFIGURATION
# ----------------------------------------------------------------------
import os
import re
import json
import pathlib
import sys
import random                     # <-- NEW: random selection
