# 7️⃣ JSON REPORT
# ----------------------------------------------------------------------
def write_json_report(
    derived_dir: pathlib.Path,
    data: List[Dict[str, Any]],
    warnings: List[str],
):
    """
    `derived_dir` must be an **absolute** path (normally `root / DERIVED_DIR_REL`).
    Writes:
      * extracted_featured.json
      * featured_warnings.txt
    """
    derived_dir.mkdir(parents=True, exist_ok=True)

    report_path   = derived_dir / EXTRACTED_JSON
    warnings_path = derived_dir / WARNINGS_MD

    report = {
        "meta": {
            "total_pages_scanned": len(data),
            "featured_pages_found": len(data),
            "warnings": len(warnings),
        },
        "featured_pages": data,
    }

    if DRY_RUN:
        print("[DRY] Would write JSON report to:", report_path)
    else:
        report_path.write_text(
            json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        print("[WROTE] JSON report ->", report_path)

    # Write warnings markdown file
    warning_lines = ["# Featured Block Generator Warnings", ""]
    if warnings:
        warning_lines.append("## Issues detected")
        warning_lines.extend(warnings)
    else:
        warning_lines.append("_No warnings_")
    warning_text = "\n".join(warning_lines)

    if DRY_RUN:
        print("[DRY] Would write warnings to:", warnings_path)
    else:
        warnings_path.write_text(warning_text, encoding="utf-8")
        print("[WROTE] Warnings ->", warnings_path)

# ----------------------------------------------------------------------
# 8️⃣ REPLACE THE FIRST CALL‑OUT ON _index.md
# ----------------------------------------------------------------------
CALL_OUT_START_RE = re.compile(r"^> \[!")   # line that begins a call‑out marker

def replace_first_callout(
    lines: List[str],
    new_block: List[str],
) -> Tuple[List[str], bool]:
    """
    Locate the **first** block that starts with `> [!` and replace *only* that
    block (including its nested `>` lines and any blank lines that belong to it)
    with *new_block*.
    """
    start = None
    end   = None

    for i, ln in enumerate(lines):
        if CALL_OUT_START_RE.match(ln):
            start = i
            j = i + 1
            while j < len(lines):
                cur = lines[j]
                if cur.strip() == "":
                    j += 1
                    continue
                if CALL_OUT_START_RE.match(cur):
                    break          # another call‑out → stop here
                if cur.startswith(">"):
                    j += 1
                    continue
                break            # non‑`>` line → end of block
            end = j
            break               # we only replace the very first call‑out

    if start is None:          # no call‑out found → nothing to do
        return lines, False

    old_block = lines[start:end]
    if old_block == new_block:  # already up‑to‑date
        return lines, False

    new_lines = lines[:start] + new_block + lines[end:]
    return new_lines, True

# ----------------------------------------------------------------------
# 9️⃣ RENDER THE CALL‑OUT BLOCK
# ----------------------------------------------------------------------
def render_featured_block(
    featured: Dict[str, Any],
    facts: List[str],
    max_facts: int = MAX_FUN_FACTS,
) -> List[str]:
    """
    Build the markdown lines for the call‑out.

    * `featured`  – dict that contains `featured_desc` and `featured_image`.
    * `facts`     – **already‑shuffled/randomised** list of fun‑facts drawn from
                    *all* pages.  We slice it to `max_facts` entries.
    """
    desc = str(featured.get("featured_desc", ""))
    img  = str(featured.get("featured_image", ""))

    # Take at most `max_facts` from the pre‑shuffled list we were given
    chosen_facts = facts[:max_facts]

    out: List[str] = [
        "> [!tip] Featured Article & Fun Facts",
        "> > [!note] Featured Article",
        f"> > {desc}",
        f"> > {img}",
        ">",                                   # blank line between sections
        "> > [!info] Did you know...",
    ]

    for f in chosen_facts:
        out.append(f"> > - {f}")

    # Exactly one trailing blank line (the caller adds the final newline)
    out.append("")
    return out

# ----------------------------------------------------------------------
# 10️⃣ MAIN DRIVER
# ----------------------------------------------------------------------
def main():
    root = find_content_root()
    all_featured: List[Dict[str, Any]] = []
    warnings: List[str] = []

    # --------------------------------------------------------------
    # Scan every markdown file and collect featured data
    # --------------------------------------------------------------
    md_files = list(iter_markdown(root))
    print(f"[SCAN] Found {len(md_files)} markdown files under {root}")

    for md in md_files:
        try:
            entry = extract_featured_from_page(md, root)
            if entry:
                all_featured.append(entry)
        except Exception as exc:
            rel = md.relative_to(root).as_posix()
            warnings.append(f"- Error processing {rel}: {exc}")

    # --------------------------------------------------------------
    # Write the JSON report & warnings *inside* content/Meta/...
    # --------------------------------------------------------------
    derived_dir_abs = root / DERIVED_DIR_REL          # <-- absolute path
    write_json_report(derived_dir_abs, all_featured, warnings)

    # --------------------------------------------------------------
    # If there is nothing to feature, exit early
    # --------------------------------------------------------------
    if not all_featured:
        print("[INFO] No pages with `featured_data` – nothing to write to home page.")
        return

    # --------------------------------------------------------------
    # Build the *global* pool of fun‑facts (from **all** pages)
    # --------------------------------------------------------------
    global_facts: List[str] = []
    for entry in all_featured:
        global_facts.extend(entry.get("fun_facts", []))

    # Shuffle once; we’ll slice later
    random.shuffle(global_facts)

    # --------------------------------------------------------------
    # Choose ONE page at random as the featured article
    # --------------------------------------------------------------
    featured_entry = random.choice(all_featured)

    # --------------------------------------------------------------
    # Load the home page and replace the first call‑out
    # --------------------------------------------------------------
    home_path = root / "_index.md"
    if not home_path.is_file():
        warnings.append("- Home page `_index.md` not found.")
        print("[WARN] Home page not found – aborting call‑out replacement.")
        return

    raw_home = home_path.read_text(encoding="utf-8")
    home_lines = raw_home.splitlines()

    new_block = render_featured_block(
        featured=featured_entry,
        facts=global_facts,          # already randomized global pool
        max_facts=MAX_FUN_FACTS,
    )

    new_home_lines, changed = replace_first_callout(home_lines, new_block)

    if not changed:
        print("[SKIP] Call‑out on home page is already up‑to‑date.")
        return

    new_home_text = "\n".join(new_home_lines).rstrip() + "\n"

    if DRY_RUN:
        print("[DRY] Would rewrite home page with new featured block.")
    else:
        home_path.write_text(new_home_text, encoding="utf-8")
        print(f"[WROTE] Updated home page -> {home_path}")

    # --------------------------------------------------------------
    # Final summary
    # --------------------------------------------------------------
    print("\n=== Summary ===")
    print(f"Featured pages discovered : {len(all_featured)}")
    print(f"Home page updated?        : {'yes' if changed else 'no'}")
    print(f"Warnings generated        : {len(warnings)}")
    if warnings:
        print("\nWarnings:")
        for w in warnings:
            print(w)

if __name__ == "__main__":
    main()
